import type { LevelFormTaskOutput } from "@e4s/ai";
import {
  PLACEMENT_RETAKE_ASSESSMENT_KEY, PLACEMENT_RETAKE_STRUCTURE, placementDefinition, placementRetakeStructureIssues, type StoredAssessmentDefinition
} from "@e4s/database";
import {
  levelFormQualityInputFromSections, splitLevelFormListeningParts, type LevelFormQualityInput, type LevelFormQualityIssue
} from "./level-form-quality.js";

/**
 * Placement retake form (owner decision 11/2026): a learner may retake placement once, on the one
 * published "Đề thi lại" form, generated by AI and approved by the Operator. It reuses the
 * level-up generator (same three slices, same output schema, auto-fix, content gate, review and
 * publish flow) with a placement scope: items spread over A1–C1 so the total still bands the
 * learner, in exactly placement-a's structure and scoring.
 */
export const PLACEMENT_RETAKE_TARGET = PLACEMENT_RETAKE_ASSESSMENT_KEY;
export type PlacementRetakeTarget = typeof PLACEMENT_RETAKE_TARGET;

/**
 * Exit (Pass Course) retake: the same once-only retake could be built for Form A, but it stays
 * hidden. The hook is ready: `assessment_retake_grants.kind` already allows 'pass_course', and the
 * grant route refuses that kind while this flag is false. Enabling it also needs a pass-course
 * retake form slot and a start path in `/assessments/pass-course/start`.
 */
export const PASS_COURSE_RETAKE_ENABLED = false;

/**
 * The published retake form has exactly placement-a's structure (owner decision): Listening
 * 15 items = Part A 4 × 1 + Part B 6 × 1 + Part C 5 × 2 (20 points), Reading 40 × 1, Writing
 * 7 + 13 (50–80 and 120–150 words), Speaking 4 × 5; 75 minutes, 100 points. The provider's
 * listening tool schema always returns 20 questions over five 4-question parts, so the prompt
 * asks for Part 1 = Part A and Parts 2–3 / 4–5 = the two halves of Parts B / C, and the form
 * keeps questions 1–4, 5–10 and 13–17 (questions 11–12 and 18–20 are reserve items).
 */
export const PLACEMENT_RETAKE_LISTENING_PLAN = [
  { key: "LA", parts: [0], firstQuestion: 0 },
  { key: "LB", parts: [1, 2], firstQuestion: 4 },
  { key: "LC", parts: [3, 4], firstQuestion: 12 }
] as const;

export const PLACEMENT_RETAKE_FORM_PROMPT = `Create a complete 75-minute, 100-point Workplace English CEFR placement test with exactly the structure of the standard placement test. This is the retake form for learners who already took the standard placement test, so every item must be new: never reuse, paraphrase closely or translate items, passages, scripts, tables or prompts of the standard placement form (placement-a). Structure (points are fixed by the form): Listening 20 points = Part A a manager announcement, 4 questions × 1 point; Part B a conversation with a supervisor, 6 questions × 1 point; Part C a discussion of a workplace policy, 5 questions × 2 points. Reading, Grammar & Vocabulary 40 standalone multiple-choice items × 1 point in four parts of ten. Writing: task 1 a short reply of 50–80 words (7 points, A2–B1), task 2 a formal email or proposal of 120–150 words (13 points, B2–C1). Speaking 4 tasks × 5 points: warm-up questions about work (A1–A2), describing workplace data or a situation (B1–B2), answering a customer's questions (B2–C1), a short presentation (B2–C1). The difficulty is NOT one target level: spread items across A1, A2, B1, B2 and C1 so the total score places the learner (bands 0–24 A1, 25–44 A2, 45–64 B1, 65–84 B2, 85–100 C1), easier to harder inside each part. Use realistic workplace situations, unambiguous answer keys, and the required JSON schema exactly.`;

export const PLACEMENT_RETAKE_SLICE_GUIDANCE = {
  listening: "Generate only the title of the whole placement test (never a section name such as \"Listening Section\"; never a single CEFR level in the title), the listening script, and exactly 20 listening questions. The script must contain exactly five clearly labelled parts (Part 1 through Part 5) with four questions each, in order. Part 1 is Part A (the announcement, A1–A2). Parts 2 and 3 are the two halves of the Part B conversation (A2–B1). Parts 4 and 5 are the two halves of the Part C discussion (B2–C1). The form keeps questions 1–4, 5–10 and 13–17; questions 11–12 and 18–20 are reserve items, so every kept question must be answerable on its own.",
  reading: "Generate only a short workplace passage (shown with the first ten items) and exactly 40 standalone grammar, vocabulary and short workplace-reading items, one point each. Keep every prompt and option concise; items 1–10, 11–20, 21–30 and 31–40 form four parts, rising from A1–A2 to B2–C1.",
  production: "Generate only exactly two writing prompts (task 1: a 50–80-word reply, A2–B1; task 2: a 120–150-word formal email or proposal, B2–C1) and four speaking prompts (warm-up questions about work, describing workplace data or a situation, answering a customer's questions, a short presentation)."
} as const;

export const PLACEMENT_RETAKE_READING_REPAIR_PROMPT = "Generate exactly one new multiple-choice reading question for the supplied passage of a mixed A1–C1 placement retake form. It must have four concise options, an unambiguous correctIndex, must not duplicate any existing prompt and must not copy the standard placement form. Each question prompt must contain only the question text. Omit part labels such as Part 1: and question numbering. Return only the structured tool input.";

export const PLACEMENT_RETAKE_TITLE = "Test đầu vào – đề thi lại";

const OPTION_VALUES = ["A", "B", "C", "D"] as const;
type Section = StoredAssessmentDefinition["sections"][number];
type Task = Section["groups"][number]["tasks"][number];

function placementSection(code: Section["code"]): Section {
  return placementDefinition.sections.find((section) => section.code === code)!;
}

function structureGroups(code: Section["code"]) {
  return PLACEMENT_RETAKE_STRUCTURE.sections.find((section) => section.code === code)!.groups;
}

function choiceTask(key: string, maxScore: number, question?: LevelFormTaskOutput["listening"]["questions"][number]): Task {
  return question ? {
    key, prompt: question.prompt, responseType: "single_choice", maxScore,
    options: question.options.map((label, index) => ({ value: OPTION_VALUES[index]!, label })),
    correctAnswer: OPTION_VALUES[question.correctIndex]!
  } : { key, prompt: "", responseType: "single_choice", maxScore, options: OPTION_VALUES.map((value) => ({ value, label: "" })) };
}

/**
 * Builds the retake form in placement-a's exact structure (counts, points, word limits, section
 * timing) from the generator output, or an empty frame for the Operator's manual draft.
 */
export function placementRetakeBlueprint(output: LevelFormTaskOutput | null, options: { manual?: boolean } = {}): StoredAssessmentDefinition {
  const listening = placementSection("listening");
  const reading = placementSection("reading");
  const writing = placementSection("writing");
  const speaking = placementSection("speaking");
  const parts = output ? splitLevelFormListeningParts(output.listening.script) : null;
  let number = 0;
  const listeningGroups = structureGroups("listening").map((group, index) => {
    const plan = PLACEMENT_RETAKE_LISTENING_PLAN[index]!;
    const first = number + 1;
    number += group.length;
    const script = parts ? plan.parts.map((part) => parts[part]?.script ?? "").filter(Boolean).join("\n\n") : "";
    const title = parts?.[plan.parts[0]]?.title ?? "";
    return {
      key: plan.key, title: `Part ${String.fromCharCode(65 + index)}${title ? ` – ${title}` : ""}`,
      instruction: `Nghe và trả lời câu ${first}–${number}.`, maxPlays: 2,
      stimulus: { type: "audio_script" as const, lines: [{ speaker: "Narrator", text: script }] },
      tasks: group.map((task, taskIndex) => choiceTask(`${plan.key}_${taskIndex + 1}`, task.maxScore, output?.listening.questions[plan.firstQuestion + taskIndex]))
    };
  });
  let readingIndex = 0;
  const readingGroups = structureGroups("reading").map((group, index) => {
    const first = readingIndex + 1;
    const tasks = group.map((task) => { readingIndex += 1; return choiceTask(`R${readingIndex}`, task.maxScore, output?.reading.questions[readingIndex - 1]); });
    return {
      key: `R${index + 1}`, title: `Questions ${first}–${readingIndex}`, instruction: "Chọn một đáp án đúng nhất.",
      ...(index === 0 && output ? { stimulus: { type: "passage" as const, text: output.reading.passage } } : {}),
      tasks
    };
  });
  const productive = (section: Section, prompts: string[] | undefined) => structureGroups(section.code).map((group, index) => ({
    key: section.groups[index]!.key, title: section.groups[index]!.title,
    instruction: section.code === "writing" ? "Hoàn thành nhiệm vụ viết." : "Hoàn thành nhiệm vụ nói.",
    tasks: group.map((task) => ({
      key: section.groups[index]!.key, prompt: prompts?.[index] ?? "", responseType: task.responseType as Task["responseType"], maxScore: task.maxScore,
      ...(task.minWords === undefined ? {} : { minWords: task.minWords }), ...(task.maxWords === undefined ? {} : { maxWords: task.maxWords })
    }))
  }));
  return {
    key: PLACEMENT_RETAKE_TARGET, kind: "placement", title: options.manual ? `${PLACEMENT_RETAKE_TITLE} — bản soạn tay` : PLACEMENT_RETAKE_TITLE,
    version: 1, totalMinutes: placementDefinition.totalMinutes, totalScore: placementDefinition.totalScore,
    sections: [
      { code: "listening", title: listening.title, durationMinutes: listening.durationMinutes, maxScore: listening.maxScore, instructions: listening.instructions, groups: listeningGroups },
      { code: "reading", title: reading.title, durationMinutes: reading.durationMinutes, maxScore: reading.maxScore, instructions: reading.instructions, groups: readingGroups },
      { code: "writing", title: writing.title, durationMinutes: writing.durationMinutes, maxScore: writing.maxScore, instructions: writing.instructions, groups: productive(writing, output?.writingPrompts) },
      { code: "speaking", title: speaking.title, durationMinutes: speaking.durationMinutes, maxScore: speaking.maxScore, instructions: speaking.instructions, groups: productive(speaking, output?.speakingPrompts) }
    ]
  };
}

/** Deterministic placement-a structure check as content-gate issues (severe: generation fails, publish blocked). */
export function placementRetakeStructureGateIssues(blueprint: StoredAssessmentDefinition): LevelFormQualityIssue[] {
  return placementRetakeStructureIssues(blueprint).map((message) => ({ code: "LEVEL_FORM_PLACEMENT_STRUCTURE", severity: "severe", section: "form", message }));
}

/**
 * Gate input for a saved retake form: its listening parts are uneven (4/6/5), so every listening
 * question is checked against the whole listening script instead of a 4-question part.
 */
export function placementRetakeQualityInput(sections: Parameters<typeof levelFormQualityInputFromSections>[0]): LevelFormQualityInput {
  const input = levelFormQualityInputFromSections(sections);
  return { ...input, listeningParts: input.listeningScript.trim() ? Array.from({ length: 5 }, () => input.listeningScript) : null };
}

/** AI input for the three generation slices (and the reading repair). */
export function placementRetakeAiInput() {
  return { targetLevel: "A1-C1" as const, scope: "placement_retake" as const, context: "workplace_english" as const, listeningQuestions: 20 as const, readingQuestions: 40 as const };
}

function normalized(text: string | undefined | null): string {
  return (text ?? "").toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu, " ").trim();
}

function sentences(text: string): string[] {
  return text.split(/(?<=[.!?])\s+|\n+/).map(normalized).filter((sentence) => sentence.length >= 40);
}

function canonicalPlacementTexts(definition: StoredAssessmentDefinition) {
  const prompts = new Set<string>();
  const items = new Set<string>();
  const stimulusSentences = new Set<string>();
  for (const section of definition.sections) {
    for (const group of section.groups) {
      const stimulus = group.stimulus;
      const stimulusText = [stimulus?.text, ...(stimulus?.lines ?? []).map((line) => line.text), ...(stimulus?.rows ?? []).map((row) => row.join(" "))].filter(Boolean).join("\n");
      for (const sentence of sentences(stimulusText)) stimulusSentences.add(sentence);
      for (const task of group.tasks) {
        const prompt = normalized(task.prompt);
        if (task.responseType === "single_choice") {
          const correct = task.options?.find((option) => option.value === task.correctAnswer)?.label;
          items.add(`${prompt}|${normalized(correct)}`);
        } else if (prompt.length >= 30) {
          prompts.add(prompt);
        }
      }
    }
  }
  return { prompts, items, stimulusSentences };
}

let canonicalCache: ReturnType<typeof canonicalPlacementTexts> | null = null;

/**
 * Deterministic guard: a retake form must never copy the canonical placement-a items. A choice
 * item is a copy when its prompt and correct answer both match a placement-a item; a productive
 * prompt when it matches verbatim; a script/passage when it repeats a full placement-a sentence.
 * Each finding is severe, so generation fails instead of saving the draft.
 */
export function placementRetakeCopyIssues(output: LevelFormTaskOutput, canonical: StoredAssessmentDefinition = placementDefinition): LevelFormQualityIssue[] {
  const texts = canonical === placementDefinition ? (canonicalCache ??= canonicalPlacementTexts(canonical)) : canonicalPlacementTexts(canonical);
  const issues: LevelFormQualityIssue[] = [];
  const choiceCopies = (section: "listening" | "reading") => output[section].questions.forEach((question, questionIndex) => {
    if (texts.items.has(`${normalized(question.prompt)}|${normalized(question.options[question.correctIndex])}`)) {
      issues.push({ code: "LEVEL_FORM_COPIES_PLACEMENT", severity: "severe", section, questionIndex, message: `Câu ${questionIndex + 1} trùng câu của đề đầu vào gốc (placement-a).` });
    }
  });
  choiceCopies("listening");
  choiceCopies("reading");
  const copiedSentence = (text: string) => sentences(text).some((sentence) => texts.stimulusSentences.has(sentence));
  if (copiedSentence(output.listening.script)) issues.push({ code: "LEVEL_FORM_COPIES_PLACEMENT", severity: "severe", section: "listening", message: "Bài nghe lặp lại câu của đề đầu vào gốc (placement-a)." });
  if (copiedSentence(output.reading.passage)) issues.push({ code: "LEVEL_FORM_COPIES_PLACEMENT", severity: "severe", section: "reading", message: "Bài đọc lặp lại câu của đề đầu vào gốc (placement-a)." });
  if ([...output.writingPrompts, ...output.speakingPrompts].some((prompt) => texts.prompts.has(normalized(prompt)))) {
    issues.push({ code: "LEVEL_FORM_COPIES_PLACEMENT", severity: "severe", section: "form", message: "Đề Viết/Nói trùng đề của đề đầu vào gốc (placement-a)." });
  }
  return issues;
}
